## 2 Geographic vs. projected CRSs

### Geographic CRS: positions are angles

```{ojs}
//| echo: false
viewof gLon = Inputs.range([-40, 85], {value: 40, step: 1, label: "Longitude (° E)"})
viewof gLat = Inputs.range([-35, 80], {value: 45, step: 1, label: "Latitude (° N)"})
```

```{ojs}
//| echo: false
{
  // A wireframe globe showing latitude and longitude as angles at Earth's center
  const g = Math.min(width, 440);
  const projection = d3.geoOrthographic().rotate([-25, -25]).fitExtent([[10, 10], [g - 10, g - 10]], {type: "Sphere"});
  const path = d3.geoPath(projection);
  const [cx, cy] = projection.translate();   // Earth's center, on screen

  // Orthographic is a parallel projection, so a point a fraction k of the way
  // from Earth's center to a surface point is drawn a fraction k of the way
  // from the screen center to that point's projection
  const inside = (lonlat, k) => {
    const [x, y] = projection(lonlat);
    return [cx + k * (x - cx), cy + k * (y - cy)];
  };
  const line = d3.line();
  const along = (f, n = 40) => d3.range(0, 1.0001, 1 / n).map(f);

  const svg = d3.create("svg").attr("viewBox", [0, 0, g, g]).style("width", g + "px").style("max-width", "100%");
  svg.append("path").attr("d", path({type: "Sphere"})).attr("fill", col.ocean).attr("stroke", col.ink);
  svg.append("path").attr("d", path(land)).attr("fill", col.land).attr("fill-opacity", 0.5);
  svg.append("path").attr("d", path(d3.geoGraticule().step([15, 15])())).attr("fill", "none").attr("stroke", col.grid).attr("stroke-width", 0.7);

  // Reference lines on the surface: the equator and Greenwich's meridian
  const equator = {type: "LineString", coordinates: d3.range(-180, 181, 2).map(x => [x, 0])};
  const greenwich = {type: "LineString", coordinates: d3.range(-90, 91, 2).map(y => [0, y])};
  svg.append("path").attr("d", path(equator)).attr("fill", "none").attr("stroke", col.ink).attr("stroke-width", 1.5);
  svg.append("path").attr("d", path(greenwich)).attr("fill", "none").attr("stroke", col.ink).attr("stroke-width", 1.5).attr("stroke-dasharray", "4 3");

  // Surface arcs: longitude along the equator (blue), latitude up the meridian (red)
  const lonArc = {type: "LineString", coordinates: along(t => [t * gLon, 0])};
  const latArc = {type: "LineString", coordinates: along(t => [gLon, t * gLat])};
  svg.append("path").attr("d", path(lonArc)).attr("fill", "none").attr("stroke", col.blue).attr("stroke-width", 4);
  svg.append("path").attr("d", path(latArc)).attr("fill", "none").attr("stroke", col.red).attr("stroke-width", 4);

  // Radii from Earth's center to (0, 0), (lon, 0), and the point
  for (const [p, c, dash] of [[[0, 0], col.ink, "4 3"], [[gLon, 0], col.blue, "4 3"], [[gLon, gLat], col.red, null]]) {
    svg.append("path").attr("d", line([[cx, cy], projection(p)])).attr("stroke", c).attr("stroke-width", 1.8).attr("stroke-dasharray", dash);
  }

  // The angles themselves, drawn inside the globe near its center
  svg.append("path").attr("d", line(along(t => inside([t * gLon, 0], 0.3)))).attr("fill", "none").attr("stroke", col.blue).attr("stroke-width", 2.5);
  svg.append("path").attr("d", line(along(t => inside([gLon, t * gLat], 0.3)))).attr("fill", "none").attr("stroke", col.red).attr("stroke-width", 2.5);
  const [lx, ly] = inside([gLon / 2, 0], 0.42);
  const [px, py] = inside([gLon, gLat / 2], 0.42);
  svg.append("text").attr("x", lx).attr("y", ly + 14).attr("text-anchor", "middle").attr("font-size", 16).attr("font-weight", 600).attr("fill", col.blue).text("λ");
  svg.append("text").attr("x", px + 10).attr("y", py).attr("font-size", 16).attr("font-weight", 600).attr("fill", col.red).text("φ");

  // Earth's center and the point
  svg.append("circle").attr("cx", cx).attr("cy", cy).attr("r", 3.5).attr("fill", col.ink);
  const [ptx, pty] = projection([gLon, gLat]);
  svg.append("circle").attr("cx", ptx).attr("cy", pty).attr("r", 6).attr("fill", col.red).attr("stroke", "#fff");
  const [gx, gy] = projection([0, 0]);
  svg.append("text").attr("x", gx - 4).attr("y", gy + 16).attr("text-anchor", "end").attr("font-size", 11).attr("fill", col.ink).text("0°, 0°");

  const ns = gLat >= 0 ? "N" : "S", ew = gLon >= 0 ? "E" : "W";
  return html`<div class="widget" style="display:${width > 720 ? "grid" : "block"};grid-template-columns:${g}px 1fr;gap:1.5rem;align-items:center">
    <div>${svg.node()}</div>
    <div style="font-size:1rem;line-height:1.6">
      <div class="readout" style="margin-bottom:.5rem">${Math.abs(gLat)}° ${ns}, ${Math.abs(gLon)}° ${ew}</div>
      <div><b style="color:${col.red}">Latitude φ</b>: angle between the equator's plane and the line to the point, measured at Earth's center</div>
      <div style="margin-top:.5rem"><b style="color:${col.blue}">Longitude λ</b>: angle around the equator from Greenwich (dashed) to the point's meridian</div>
    </div>
  </div>`;
}
```

- Units: **degrees** (angles, not distances)
- Longitude −180° to 180°; latitude −90° to 90°
- Examples: **WGS 84** (GPS), **NAD83** (US Census)

### Projected CRS: positions are distances on a flat grid

```{=html}
<div class="widget" style="text-align:center">
